def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def regions(n, separators):
        out, start = [], 0
        for x in separators:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = regions(h, sep_rows), regions(w, sep_cols)
    cells = []
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            marks = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != bg]
            cells.append((len(marks), ri, ci, marks))

    _, sri, sci, pattern = max(cells)
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            if (r1-r0, c1-c0) != (rs[sri][1]-rs[sri][0], cs[sci][1]-cs[sci][0]):
                continue
            for dr, dc, color in pattern:
                out[r0+dr][c0+dc] = color
    return out
